INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(17, 'koKR', 'Składniki z Uldamanu', 'Słyszałem o niedawno odkrytej roślinie, którą nazywają purpurowymi kapeluszami grzyba. Rosną w kępach na wykopaliskach w Uldamanie – można je znaleźć w pierwszych tunelach i głęboko w mniej zbadanych częściach. Chcę zbadać, czy nadają się do alchemii, i tu właśnie wkraczasz ty.$B$BZnajdź kępy purpurowych kapeluszy i przynieś mi tuzin kapeluszy. Tylko uważaj: potrącone kępy potrafią sypnąć trującymi zarodnikami.$B$BZrób to dla mnie, a upichcę ci porcję jednego z moich słynnych przywracających eliksirów!', 'Przynieś 12 purpurowych kapeluszy grzyba Ghakowi Kojodłoniowi w Thelsamarze.', '', 'Wróć do Ghaka Kojodłonia w Thelsamarze w Loch Modan.', '', '', '', '', 0),
(161, 'koKR', 'Mroczna groźba', 'Jeśli moje podejrzenia są słuszne, to jakiś proch wybuchowy. Musi go zbadać znawca materiałów wybuchowych, żebyśmy wiedzieli, z czym mamy do czynienia. Ashlana Kamiennoszyderczego przydzielono do regimentu, który strzeże Dun Modr i Mostu Thandol. Muszę cię prosić o poważną i niebezpieczną podróż, $N.$b$bPrzejdź przez Bramę Algaz, idź drogą przez Bagniska i odszukaj Kamiennoszyderczego w Dun Modr. Posłuchaj mojej rady: trzymaj się dróg i nigdzie się nie zatrzymuj!', 'Główny inżynier Hinderweir chce, żebyś $gzaniósł:zaniosła; dziwnie pachnący proszek Ashlanowi Kamiennoszyderczemu, znawcy materiałów wybuchowych w Dun Modr na Bagniskach.', '', '', '', '', '', '', 0),
(199, 'koKR', 'Mroczna groźba', 'Pobierasz próbkę dziwnie pachnącego proszku.', 'Wróć do głównego inżyniera Hinderweira i pokaż mu znaleziony trop.', '', '', '', '', '', '', 0),
(217, 'koKR', 'W obronie ziem królewskich', '$N, nasi zwiadowcy ustalili, kto dowodzi ostatnim najazdem troggów. Wygląda na to, że te bestie w Loch Modan słuchają wodza imieniem Grawmug. Grawmug jest jednak dobrze strzeżony. Dwaj jego najlepsi strażnicy, Zgrzytacz i Zabijaka, nie odstępują go na krok.$b$bJeśli czujesz się na siłach, $N, chcę, żebyś $gpoprowadził:poprowadziła; wyprawę, która ma zgładzić Grawmuga i jego dwóch zbirów. Jeśli troggi stracą przywódców, może zdołamy zepchnąć te bestie z powrotem pod ziemię.', 'Zabij przywódcę troggów, Grawmuga, i jego dwóch strażników, Zgrzytacza i Zabijakę, a potem zamelduj się u kapitana Rugelfussa w południowej wieży strażniczej.', '', 'Wróć do kapitana Rugelfussa w Dolinie Królów w Loch Modan.', '', '', '', '', 0),
(224, 'koKR', 'W obronie ziem królewskich', 'Musimy bronić Lochu, $N! Tylu królewskich żołnierzy dzielnie walczy na dalekich polach bitew, że tu, w domu, ledwie dajemy sobie radę. Troggi wyłażą z każdej szczeliny! Ta troggowa plaga to największe zagrożenie dla Żelaznej Kuźni. Trzeba wytępić te obrzydliwe mutanty.$b$bPotrzebujemy cię, $gdzielny poszukiwaczu:dzielna poszukiwaczko; przygód – ruszaj i rozgrom troggów. Zabij 10 troggów z Kamiennych Drzazg i 10 zwiadowców z Kamiennych Drzazg, a potem wróć z meldunkiem.', 'Górski strażnik Brukokrzem z południowej wieży strażniczej chce, żebyś $gzabił:zabiła; 10 troggów z Kamiennych Drzazg i 10 zwiadowców z Kamiennych Drzazg.', '', 'Wróć do górskiego strażnika Brukokrzema na Przełęczy Północnej Bramy w Dun Morogh.', '', '', '', '', 0),
(237, 'koKR', 'W obronie ziem królewskich', 'Górski strażnik Brukokrzem nie mógł się ciebie nachwalić. Dlatego powierzę ci zadanie najwyższej wagi. Musimy nieustannie naciskać na najeźdźców, dopóki nasi krasnoludzcy bracia nie wrócą z frontu Przymierza.$b$bRuszaj na południowe wzgórza i zabij 10 czaszkotłuków z Kamiennych Drzazg i 10 jasnowidzów z Kamiennych Drzazg. Twoje ataki dadzą nam trochę czasu. Zamelduj się, kiedy wykonasz zadanie.', 'Górski strażnik Żwirogęby z południowej wieży strażniczej chce, żebyś $gzabił:zabiła; 10 czaszkotłuków z Kamiennych Drzazg i 10 jasnowidzów z Kamiennych Drzazg, a potem $gwrócił:wróciła; do niego z meldunkiem.', '', 'Wróć do górskiego strażnika Żwirogębego w Dolinie Królów w Loch Modan.', '', '', '', '', 0),
(250, 'koKR', 'Mroczna groźba', 'Dzięki gwiazdom, że ktoś jeszcze troszczy się o Tamę. Najpierw zniszczenie Mostu Thandol, potem splądrowanie Dun Modr! Nie mam wątpliwości, że Tama będzie następnym celem Czarnorytych. Większość tutejszej straży przeniesiono na front Przymierza, łącznie z moim najlepszym inspektorem.$b$bDlatego potrzebuję ciebie, $N. Widziałem saperów Czarnorytych kręcących się przy wschodniej rampie Tamy. Zbadaj okolicę i przynieś mi jakiś trop.', 'Zbadaj okolicę wschodniej rampy Tamy i przynieś głównemu inżynierowi Hinderweirowi trop, który mógłby zdradzić, co knują Czarnoryci.', '', '', '', '', '', '', 0),
(255, 'koKR', 'Najemnicy', 'Dwa miesiące czekania, żeby usłyszeć z Żelaznej Kuźni, że łaskawie przydzielą nam garstkę żołnierzy do obrony, i kolejne dwa, zanim tu dotrą! Dość źle, że nasze miasteczko jest bez ochrony, ale wykopaliska i tama – tama! – też są wystawione na ataki.$b$bWygląda na to, że nie mam wyboru. Muszę wynająć miecze.$b$bMoże ty? Wyglądasz na kogoś, kto się nada. Banda ogrów rozbiła obóz na północny wschód od jeziora. Może to właśnie ty usuniesz zagrożenie dla naszego miasteczka?', 'Sędzia Tęponosy z Thelsamaru wynajął cię, żebyś $gzabił:zabiła; 4 ogry z Mo\'grosh, 4 osiłki z Mo\'grosh i 4 egzekutorów z Mo\'grosh.', '', 'Wróć do sędziego Tęponosego w Loch Modan.', '', '', '', '', 0),
(256, 'koKR', 'POSZUKIWANY: Chok\'sul', 'Z rozkazu sędziego Thelsamaru:$b$bChok\'sul, ogr uważany za przywódcę i organizatora napaści na miasteczko Thelsamar, Kamienną Tamę i wykopaliska, jest poszukiwany martwy – wszelkimi dostępnymi środkami.$b$bKto dostarczy sędziemu dowód śmierci Chok\'sula, otrzyma nagrodę pieniężną.$b$bChok\'sula ostatnio widziano w obozowisku ogrów w północno-wschodniej części Loch Modan.', 'Zabij Chok\'sula i przynieś jego głowę sędziemu Tęponosemu w Thelsamarze.', '', 'Wróć do sędziego Tęponosego w Loch Modan.', '', '', '', '', 0),
(257, 'koKR', 'Przechwałki łowcy', 'Myślisz, że dorównasz sprytem Darylowi Śmiałemu, co? Raczej nie! Oczywiście możesz spróbować. Oto wyzwanie, które chyba cię przerasta, więc nie przejmuj się, jeśli nie dasz rady.$b$bW Loch Modan zagnieździło się stado sępów. Może spróbujesz ustrzelić kilka tych bestii? Wiesz co, jeśli podołasz mojemu wyzwaniu w piętnaście minut, dam ci mój łuk albo strzelbę.$b$b<Mierzy cię lekceważącym spojrzeniem.>$b$bI tak nie wygląda na to, żebyś $gmiał:miała; wiele do stracenia.', 'Zabij 6 górskich sępów i w ciągu 15 minut wróć do Daryla Młodzika w Stróżówce Obieżyświatów.', '', 'Wróć do Daryla Młodzika w Stróżówce Obieżyświatów w Loch Modan.', '', '', '', '', 0),
(258, 'koKR', 'Wyzwanie łowcy', '$Nasz, tak? Widzę, że aż pękasz z dumy po pierwszej próbie, hm? Jak już mówiłem, to żaden wielki wyczyn.$b$bSpróbuj swoich sił w polowaniu na dziki. Wierz mi, to nie polowanie na dziki w Dolinie Zimnej Grani, więc lepiej na nie uważaj. Tym razem dam ci tylko dwanaście minut.$b$bNie przejmuj się, jeśli ci się nie uda. Jeśli dasz radę, oddam ci ostatnią koszulę!$b$bOpowiadałem ci już, skąd mam moją słynną bliznę? Nie? To było dwa lata temu...', 'Zabij 5 sędziwych górskich dzików i w ciągu 12 minut wróć do Daryla Młodzika w Stróżówce Obieżyświatów.', '', 'Wróć do Daryla Młodzika w Stróżówce Obieżyświatów w Loch Modan.', '', '', '', '', 0),
(263, 'koKR', 'W obronie ziem królewskich', 'Górscy strażnicy mówią, że $gjesteś odważny i zdolny:jesteś odważna i zdolna;, $N. Przyda się nam tu ktoś taki jak ty. Kłopot z troggami wcale nie maleje. Rezerwy wezwano na front i zostaliśmy tu całkiem sami. Ale skoro mamy tu kogoś z doświadczeniem, zobaczmy, co potrafisz.$b$bRuszaj i zabij 10 szamanów z Kamiennych Drzazg i 10 kościołamów z Kamiennych Drzazg. Zobaczymy, czy jesteś $gwart:warta; swojej sławy, $gPogromco:Pogromczyni; Troggów.', 'Górski strażnik Ścianotłuk z południowej wieży strażniczej chce, żebyś $gzabił:zabiła; 10 szamanów z Kamiennych Drzazg i 10 kościołamów z Kamiennych Drzazg.', '', 'Wróć do górskiego strażnika Ścianotłuka w Dolinie Królów w Dun Morogh.', '', '', '', '', 0),
(267, 'koKR', 'Zagrożenie ze strony troggów', 'Może wiesz, a może nie, o zagrożeniu, jakie troggi stanowią dla krasnoludzkich ziem. Rezerwę Żelaznej Kuźni wezwano na front Przymierza, więc został nam ledwie ułamek sił potrzebnych do obrony tych ziem. Mój regiment ma pilnować tutejszej Bramy i nie możemy opuścić posterunku w obawie przed najazdem.$b$bAle trzeba przycisnąć te przeklęte troggi, które czają się na wzgórzach. Jeśli podołasz zadaniu, uderz na nie. Przynieś mi na dowód 8 kamiennych zębów trogga.', 'Przynieś 8 kamiennych zębów trogga kapitanowi Rugelfussowi w południowej wieży strażniczej.', '', 'Wróć do kapitana Rugelfussa na Przełęczy Północnej Bramy w Dun Morogh.', '', '', '', '', 0),
(271, 'koKR', 'Zemsta Vyrin', 'Nie masz pewnie ochoty na małą odpłatę dla Jego Śmiałości? Daryl ma pewne umiejętności, choć boli mnie, że muszę to przyznać.$b$bRok temu w Stróżówce Obieżyświatów polowano na wielkiego niedźwiedzia, ale żadnemu z łowców się nie poszczęściło. Więc Daryl postanowił sam spróbować. Jedyne, co z tego wyniósł, to ta paskudna blizna nad okiem.$b$bZabij tego niedźwiedzia, a założę się, że choć raz nawet Darylowi odejmie mowę.$b$bNiedźwiedź, Stary Smoluch, kręci się wokół swojego legowiska na wzgórzach nad Thelsamarem.', 'Zabij Starego Smolucha i pokaż owoc swojej pracy Darylowi Młodzikowi w Stróżówce Obieżyświatów.', '', 'Wróć do Daryla Młodzika w Stróżówce Obieżyświatów w Loch Modan.', '', '', '', '', 0),
(273, 'koKR', 'Zaopatrzenie dla wykopalisk', 'Ale jeszcze nie jest za późno, możesz poszukać Huldara. Nie mógł zajść daleko – Miran i Saean są silni, ale objuczeni tymi beczkami nie pójdą szybciej, niż się da.$b$bIdą zwykłą drogą na wykopaliska: wychodzą z miasteczka na południe i ciągną wzdłuż brzegu Lochu.$b$bNie powinno być kłopotu z ich znalezieniem, chyba że już dotarli na miejsce.', 'Porozmawiaj z Huldarem.', 'Znajdź Huldara, Mirana i Saeana', 'Porozmawiaj z Huldarem nad Lochem w Loch Modan.', '', '', '', '', 0),
(274, 'koKR', 'Mroczna groźba', 'To nie jest zwyczajny proch strzelniczy. Popatrz na te malutkie srebrne kryształki. I ten charakterystyczny zapach! Jasne jak słońce, że to proch seaforium. Samo seaforium jest dość niegroźne. Ale jak zamoknie, mogłoby wysadzić Żelazną Kuźnię z góry w powietrze.$b$bReakcję chemiczną można zneutralizować mieszanką czterech składników: jadu czyhacza, sproszkowanego kryształu z Mo\'grosh, łzy krokoliszka i tego tu rozbrajającego koloidu. A teraz powiedz o tym Hinderweirowi, zanim będzie za późno!', 'Ashlan Kamiennoszyderczy chce, żebyś $gwrócił:wróciła; do głównego inżyniera Hinderweira w Loch Modan i $gpowiadomił:powiadomiła; go o nowym odkryciu.', '', '', '', '', '', '', 0),
(278, 'koKR', 'Mroczna groźba', 'Natychmiast zacznij zbierać materiały do rozbrojenia, $N. Jad czyhacza zdobędziesz z miejscowych pająków w Loch Modan. Łzy krokoliszka też znajdziesz tu, nad Lochem. Ale o kryształ z Mo\'grosh będzie bardzo trudno. Ogry na północnym wschodzie je wydobywają, ale to wielka rzadkość.$b$bMusimy być gotowi, żeby udaremnić atak Czarnorytych! Wróć do mnie, gdy zbierzesz, co trzeba, a ja przygotuję mieszankę.', 'Główny inżynier Hinderweir chce, żebyś $gzebrał:zebrała; jad czyhacza, kryształ z Mo\'grosh i łzę krokoliszka.', '', 'Wróć do głównego inżyniera Hinderweira VII przy Kamiennej Tamie w Loch Modan.', '', '', '', '', 0),
(280, 'koKR', 'Mroczna groźba', 'Dziś rano widziałem, jak buntownicy Czarnorytych płyną w stronę Tamy z wielką beczułką. Nie było tu żadnego górskiego strażnika, żeby ich powstrzymać! Obawiam się, że podłożyli seaforium u podstawy Tamy i w każdej chwili może wybuchnąć! Pozwól, że połączę wszystkie składniki w rozbrajającą mieszankę. No, gotowe.$b$bA teraz weź tę mieszankę i wmieszaj ją do beczułki, zanim będzie za późno! Pospiesz się!', 'Główny inżynier Hinderweir chce, żebyś $gzanurkował:zanurkowała; do podstawy tamy, $godnalazł:odnalazła; beczułkę z prochem i $gwmieszał:wmieszała; do niej rozbrajającą mieszankę, by zapobiec wybuchowi.', '', '', '', '', '', '', 0),
(283, 'koKR', 'Mroczna groźba', 'Beczułka lekko syczy.', 'Wygląda na to, że rozbrajająca mieszanka zadziałała. Wróć do głównego inżyniera Hinderweira i przekaż mu dobre wieści.', '', '', '', '', '', '', 0),
(297, 'koKR', 'Zbieranie bożków', 'Niedawno, tuż zanim na wykopaliskach pojawiły się troggi, odkryliśmy mnóstwo dziwnych, rzeźbionych bożków. Nie zdążyliśmy ich jednak zbadać, bo zaraz po tym odkryciu troggi przegnały nas z ruin! A te bożki dziwnie działają na troggi. Wpadają przez nie w szał!$B$BPrzynieś mi 8 bożków – chcę je zbadać i nie chcę, żeby zostały w łapach troggów! Znajdziesz je przy troggach, które zalęgły się na wykopaliskach.', 'Przynieś Magmarowi Srogorąbowi 8 rzeźbionych kamiennych bożków.', '', 'Wróć do Magmara Srogorąba na Wykopaliskach Ironbanda w Loch Modan.', '', '', '', '', 0),
(298, 'koKR', 'Raport z postępów wykopalisk', 'Trzeba wysłać do Thelsamaru raport z postępów – raport z postępów i ponowną prośbę o więcej prochu strzelniczego! Oto raport. Zanieś go Jernowi Rogohełmowi. To nasz łącznik w Thelsamarze.$B$BTo nietrudne zadanie, ale ktoś musi je wykonać.', 'Zanieś raport postępów Ironbanda Jernowi Rogohełmowi w Thelsamarze.', '', '', '', '', '', '', 0),
(307, 'koKR', 'Brudne łapska', 'Kopalnia Srebrnego Strumienia na wschodzie dawno się wyczerpała. Liga Górników zrobiła z niej skład, ale teraz zalęgły się tam koboldy i kładą swoje brudne łapska na porządnych, krasnoludzkich narzędziach!$B$BNiedługo wykurzymy to robactwo, ale Liga chce, żeby ktoś wyniósł jej sprzęt z kopalni, zanim my, wojacy, tam wparujemy i wszystko porozwalamy. To będzie trudna wyprawa w głąb – lepiej weź ze sobą kompanów.$B$BSprzęt jest przechowywany w skrzyniach Ligi Górników w całej kopalni. Powodzenia.', 'Idź do Kopalni Srebrnego Strumienia i zbierz 4 ładunki sprzętu górników.$B$BWróć do górskiego strażnika Gromdardy.', '', 'Wróć do górskiego strażnika Gromdardy w Stacji Algaz w Loch Modan.', '', '', '', '', 0),
(309, 'koKR', 'Ochrona transportu', '$gGotowy:Gotowa; do drogi, $n?$b$bNajpierw musimy dostarczyć ten proch Ironbandowi. Sporo tego jak dla mnie do dźwigania, a w tych stronach bywa niebezpiecznie – i kto wie, co jeszcze Czarnoryci dla mnie szykują.$b$bBędę dużo spokojniejszy, jeśli pójdziesz ze mną.', 'Dopilnuj, żeby Miran i transport dotarli na wykopaliska, a potem powiadom poszukiwacza Ironbanda.', 'Odprowadź Mirana na wykopaliska', 'Wróć do poszukiwacza Ironbanda na Wykopaliskach Ironbanda w Loch Modan.', '', '', '', '', 0),
(385, 'koKR', 'Polowanie na krokoliszki', 'Do Loch Modan ściąga wielu łowców, żeby polować na nasze słynne krokodyle. Zawsze znajdą się kupcy, którzy szukają skór krokoliszków na odzież czy zbroje, są też tacy, którzy lubią smak ich mięsa.$b$bTrochę tym handlujemy, ale niewiele, bo krokoliszki są dzikie i okopały się na wyspach na Lochu. Ale niech cię to nie zniechęca – mocowanie się z paszczą takiej bestii to niezłe przeżycie.$b$bKiedyś, pamiętam...', 'Zdobądź 5 kawałków mięsa krokoliszka i 6 skór krokoliszka dla Marka Żelaznosercego w Stróżówce Obieżyświatów.', '', 'Wróć do Marka Żelaznosercego w Loch Modan.', '', '', '', '', 0),
(416, 'koKR', 'Łapanie szczurów', 'Na zachodzie mamy prawdziwą plagę. Koboldy z Tunelowych Szczurów wprowadziły się na pogórze, ryją nory i zapaskudzają nasze ziemie swoim brudem!$B$BChcemy się ich pozbyć. Poluj na nie, przynoś mi ich uszy i zgarnij nagrodę.$B$BKoboldy z Tunelowych Szczurów i ich nory znajdziesz na zachód od Thelsamaru, porozrzucane po zboczu góry.', 'Przynieś 12 uszu Tunelowych Szczurów górskiemu strażnikowi Kadrellowi w Thelsamarze.', '', 'Wróć do górskiego strażnika Kadrella w Thelsamarze w Loch Modan.', '', '', '', '', 0),
(418, 'koKR', 'Kaszanka z Thelsamaru', 'W Thelsamarze nigdy nie brakuje pustych brzuchów – dzieciaki wbiegają i wybiegają, robotnicy z wykopalisk wracają po ciężkim dniu pracy. Słyniemy z naszej kaszanki, pewnie jeszcze nie $gpróbowałeś:próbowałaś;?$b$bNie? No cóż, u nas na posiłek trzeba zapracować, i nie myśl sobie, że skoro jesteś jakąś ważną personą, to będziesz wyjątkiem.$b$bPotrzebuję niedźwiedziego mięsa, jelit dzika na osłonki i pajęczej posoki do przyprawy. Zdobądź mi to wszystko, a gotowanie zostaw Vidrze!', 'Przynieś 3 kawałki niedźwiedziego mięsa, 3 jelita dzika i 3 pajęcze posoki Vidrze Ciepłopiec w Thelsamarze.', '', 'Wróć do Vidry Ciepłopiec na Grani Siwej Łapy w Loch Modan.', '', '', '', '', 0),
(436, 'koKR', 'Wykopaliska Ironbanda', 'Poszukiwacz Ironband kieruje wykopaliskami w prastarych ruinach na wschód od jeziora. Ostatnio prace idą mu powoli, zwłaszcza jak na to, ile zapasów mu wysłaliśmy.$B$BIronband to krzepki, uczciwy krasnolud, który ceni wyniki, więc martwię się, że jakieś siły działają przeciwko niemu.$B$BIdź na Wykopaliska Ironbanda i pomów z Magmarem Srogorąbem. To on zarządza sprawami na miejscu i będzie wiedział, skąd te opóźnienia.$B$BŻeby dotrzeć na wykopaliska, obejdź południowy kraniec jeziora, a potem idź na wschód.', 'Porozmawiaj z odkrywcą Srogorąbem.', '', '', '', '', '', '', 0),
(454, 'koKR', 'Po zasadzce', 'Zanim doszło do tej... sprawy, woziliśmy beczki z prochem tam i z powrotem, kursami. Teraz musimy podzielić robotę: Miran zabiera beczki, a ja pilnuję reszty.$b$bNie czuję się pewnie, puszczając Mirana samego z resztą transportu. Kiedy będzie gotów do drogi, może odprowadzisz go w następnym kursie?', 'Porozmawiaj z Miranem.', '', '', '', '', '', '', 0),
(455, 'koKR', 'Przeprawa przez Algaz', 'Orkowie z klanu Smoczych Paszcz mają swoją kryjówkę na Bagniskach. A teraz rozpełzli się aż do Dun Algaz! Nie możemy pozwolić, żeby się tu zadomowili, bo Loch Modan zostanie odcięte od Przystani Menethilów, naszego portu i twierdzy na Bagniskach.$B$BPrzebij się przez Dun Algaz na Bagniska i dla porządku zabij kilku orków! Zamelduj się u Valstaga Żelaznoszczękiego w Przystani Menethilów.$B$BDo Menethilów dojdziesz przez Dun Algaz, a potem drogą na północ i na rozwidleniu na zachód.$B$BLiczymy na ciebie, $N. Nie zawiedź nas.', 'Przejdź przez Dun Algaz.$B$BZabij 8 zwiadowców Smoczych Paszcz i 6 siepaczy Smoczych Paszcz.$B$BZamelduj się u Valstaga Żelaznoszczękiego w Przystani Menethilów.', 'Przejdź przez Dun Algaz', 'Wróć do Valstaga Żelaznoszczękiego w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(468, 'koKR', 'Zgłoś się do górskiego strażnika Rockgara', 'Górski strażnik Rockgar szuka ochotników na wyprawę przez Dun Algaz na Bagniska.$B$BJeśli masz ochotę zamoczyć buty w tej rozmokłej krainie na północy, pomów z Rockgarem w Dun Algaz. Do Dun Algaz dojdziesz drogą na północ, za wieżą strażniczą.', 'Porozmawiaj z górskim strażnikiem Rockgarem.', '', '', '', '', '', '', 0),
(531, 'koKR', 'Zemsta Vyrin', 'Na Światłość! Nie wnoś takich rzeczy do Stróżówki... to niehigieniczne, niewypowiedziane, nie... nie... niehigieniczne!$b$bPo prostu wynieś to stąd, dobrze? Nikt nie chce oglądać twojego zakrwawionego trofeum, naprawdę!', 'Zanieś głowę Starego Smolucha Vyrin Rączy Wiatr w Stróżówce Obieżyświatów.', '', '', '', '', '', '', 0),
(704, 'koKR', 'Los Agmonda', 'Ostatni raport, jaki dostałem od Agmonda, jest niepokojący, a teraz, gdy Agmond nie żyje, tym bardziej! Wspomniał, że jego kopacze odkopali „prastare urny” na wykopaliskach pod Uldamanem. Obawiam się, że urny, które tam znalazł, rozjuszyły troggi, tak samo jak bożki, które znalazłem tutaj.$B$BPotrzebuję tych urn do naszych badań. Idź na wykopaliska w Uldamanie, zbierz urny i wróć do mnie.', 'Przynieś 4 rzeźbione kamienne urny poszukiwaczowi Ironbandowi w Loch Modan.', '', 'Wróć do poszukiwacza Ironbanda na Wykopaliskach Ironbanda w Loch Modan.', '', '', '', '', 0),
(721, 'koKR', 'Znak nadziei', '$N, odnajdziesz go? Odnajdziesz Młotopalcego w Uldamanie?$B$BJeśli te plugawe krasnoludy z Cienistej Kuźni trzymają go jako zakładnika, żeby wyciągnąć z niego, co wie o wykopaliskach tytanów, to cała Żelazna Kuźnia może mieć wielkie kłopoty.$B$BCzarnoryci od dawna szukają magii, dzięki której zrobią potężniejsze golemy. Młotopalcy robił to samo, jasna rzecz, ale tylko po to, żeby ich powstrzymać.$B$BPewnie trzymają go przy życiu, dopóki nie wyciągną z niego, co wie. Musisz się spieszyć, jeśli chcesz go uratować!', 'Odnajdź Młotopalcego Greza w Uldamanie.', '', '', '', '', '', '', 0),
(722, 'koKR', 'Amulet tajemnic', '$gOdważny:Odważna; z ciebie... <kaszel>... skoro $gprzyszedłeś:przyszłaś; po mnie do Uldamanu.$B$BJeśli naprawdę chcesz pomóc... staremu Młotopalcemu, to... <kaszel>... musisz znaleźć... mój amulet.$B$BMa go Głębocień... Magregan Głębocień. Kręci się gdzieś... po ruinach, na pewno. Ten amulet ich zaprowadzi... <kaszel>... prosto do zwojów, jeśli nikt go nie powstrzyma. Wszystko w twoich rękach, $N. Proszę... zdobądź ten amulet.$B$BTe zwoje na pewno pomogą Czarnorytym stworzyć jeszcze potężniejsze golemy. Ja to wiem. Czuję to w kościach.', 'Znajdź amulet Młotopalcego i zwróć mu go w Uldamanie.', '', 'Wróć do Młotopalcego Greza w Uldamanie.', '', '', '', '', 0),
(723, 'koKR', '', '<Młotopalcy przyciska dłonie do ran i przez chwilę zbiera siły, zanim znów się odezwie.>$B$BZnajdź Ryedola, $N. Zanieś mu mój amulet. <kaszel, kaszel> On... <kaszel> będzie wiedział, co robić. Wie, że szukałem korzeni naszego ludu, i wie... <kaszel>... że moim zadaniem było też powstrzymać klan Cienistej Kuźni. Nie wolno im pozwolić znaleźć tych zwojów... <kaszel>', 'Zanieś amulet Młotopalcego poszukiwaczowi Ryedolowi na Bezludziu.', '', '', '', '', '', '', 0),
(738, 'koKR', 'Odnajdź Agmonda', 'Poszukiwacz Agmond kierował naszymi wykopaliskami na Bezludziu, na południowym zachodzie. Mówię „kierował”, bo... cóż, od tygodni nie mam od niego wieści. Musisz odnaleźć Agmonda, żebym dostał jego raport.$B$BOstatnio słyszałem, że Agmond był na najdalej wysuniętych na południe wykopaliskach na Bezludziu – to malutka placówka za Fortecą Angor. Ja zacząłbym szukać właśnie tam.', 'Odnajdź Agmonda.', '', '', '', '', '', '', 0),
(739, 'koKR', 'Murdaloc', 'Ślady Agmonda prowadzą z zachodu. Po krwawych smugach na skałach i piasku łatwo poznać, że krasnolud czołgał się spory kawałek.$B$BI tu umarł.$B$BPo dokładnych oględzinach widać słowo „Murdaloc” niezgrabnie wydrapane na kawałku piaskowca z Bezludzia.$B$BWydrapane tuż obok martwej dłoni Agmonda.', 'Zabij zabójcę Agmonda, Murdaloca.$B$BZabij 12 kościołamów z Kamiennego Skarbca.$B$BZamelduj się u poszukiwacza Ironbanda w Loch Modan.', '', 'Wróć do poszukiwacza Ironbanda na Wykopaliskach Ironbanda w Loch Modan.', '', '', '', '', 0),
(912, 'koKR', 'Przebranie trogga z Kamiennych Drzazg', '', '', '', '', '', '', '', '', 0),
(1339, 'koKR', 'Zadanie górskiego strażnika Gromdardy', 'Słyszałem, że górski strażnik Gromdarda szuka gońca. Kogoś, kto trochę dla niego popodróżuje. Co ty na to? Nadajesz się do tej roboty?$B$BJeśli tak, znajdziesz Gromdardę na szczycie północnej wieży strażniczej.', 'Porozmawiaj z górskim strażnikiem Gromdardą.', '', '', '', '', '', '', 0),
(1655, 'koKR', 'Dostawa rudy Bailora', 'Ach, ależ mnie $gprzestraszyłeś, chłopie:przestraszyłaś, kobieto;! Nie widzisz, że się zamyśliłem?$B$BŻe co? Dostawa Jordana... do Żelaznej Kuźni. Aaa, tak, wiem, o czym gadasz. Ogry z Mo\'grosh... to one zabrały rudę mojego starego kumpla. Karawana szła tu z Bagnisk i wpadła w zasadzkę. Strażnik, co przeżył ich napaść, zmarł raptem parę dni temu – uzdrowiciel nie zdążył do niego na czas.$B$BJak chcesz tę dostawę, musisz iść na północny wschód, przez Loch. Musi tam gdzieś być.', 'Przynieś dostawę rudy Jordana Bailorowi Kamiennorękiemu w Loch Modan.', '', 'Wróć do Bailora Kamiennorękiego w Loch Modan.', '', '', '', '', 0),
(2038, 'koKR', 'Zaginiony sprzęt Binglesa', 'Jakby tego było mało, że rozbiłem się w Lochu, to jeszcze troggi z pobliskiej wyspy napadły na mnie i ukradły moje narzędzia i specjalne materiały wybuchowe – Blastencapper Blastenheimera. Bez żyrokoptera i bez materiałów wybuchowych nasza sprawa nie ma żadnych szans!$B$BOdzyskaj moje narzędzia i znajdź mój Blastencapper, $N. Za Gnomoregan!', 'Znajdź i zwróć rzeczy Binglesa:$B$Bklucz Binglesa, śrubokręt Binglesa, młotek Binglesa i Blastencapper Binglesa.', '', 'Wróć do Binglesa Blastenheimera nad Lochem w Loch Modan.', '', '', '', '', 0),
(2500, 'koKR', 'Składniki z Bezludzia', 'Chętnie skorzystałbym z twoich usług. Jestem alchemikiem niemałej sławy i szukam pomocy w zdobyciu pewnych składników, które można znaleźć na Bezludziu.$B$BŻeby uzupełnić zapasy, potrzebuję następujących rzeczy: pięciu żołądków sępa, dziesięciu kłów skalnego kojota i pięciu odłamków skalnego żywiołaka. Oczywiście zdobędziesz je z samych bestyjek; jeśli walka to nie twoja specjalność, znajdź przyjaciół, dla których jest.$B$BZdobądź dla mnie te rzeczy, a zarobisz na tym trochę grosza.$B$BNo i co ty na to?', 'Zdobądź na Bezludziu składniki, których potrzebuje Ghak Kojodłoń, a potem wróć do niego do Thelsamaru.', '', 'Wróć do Ghaka Kojodłonia na Grani Siwej Łapy w Loch Modan.', '', '', '', '', 0),
(2501, 'koKR', 'Składniki z Bezludzia II', 'Bardzo mi $gpomogłeś:pomogłaś;, $N. Chciałbym cię nagrodzić przepisem na ten sam wywar, który ci wcześniej dałem, ale muszę cię prosić o przysługę, i to całkiem niebezpieczną.$B$BW tej kasetce są trzy puste naczynia taumaturgiczne; przepaja je aura dostrojenia, która wyssie krew ze osmalonego strażnika – smoka z Bezludzia. Użycie naczynia na bestii mocno ją rozwścieczy, więc uważaj. Kiedy napełnisz wszystkie trzy, przynieś mi je.$B$BZrób to, a przepis będzie twój.', 'Użyj pustych naczyń taumaturgicznych na osmalonych strażnikach, smokach z Bezludzia. Kiedy je napełnisz, zanieś je Ghakowi Kojodłoniowi w Thelsamarze.', '', 'Wróć do Ghaka Kojodłonia w Thelsamarze w Loch Modan.', '', '', '', '', 0),
(3181, 'koKR', 'Róg bestii', 'Gigantyczny róg jest pełen rys i pęknięć. W jego chropowatą powierzchnię wbił się dziwny metalowy przedmiot.$B$BPrzyglądając się bliżej, zauważasz, że ten metal to w rzeczywistości ułamane ostrze topora. Na metalu wyryto następujące słowa:$B$BWłasność górskiej strażniczki Kamyczek.$B$BGdy próbujesz wyciągnąć ułamane ostrze, rozpada się na milion kawałków.$B$BOjej!', 'Zanieś gigantyczny róg Margola górskiej strażniczce Kamyczek.$B', '', '', '', '', '', '', 0),
(6387, 'koKR', 'Prymusi', 'Do moich drzwi puka wielu młodych krasnoludów, którzy chcą się nauczyć górniczego fachu. A jeśli górnikowi coś jest potrzebne bardziej niż cokolwiek innego, to kilof!$B$BMam listę uczniów górnictwa, którzy świetnie spisali się na lekcjach i zasłużyli na honorowy kilof. Zanieś moją listę Golnirowi Głazopalcowi w Żelaznej Kuźni. On przygotuje kilofy.$B$BNajszybciej dostaniesz się do Żelaznej Kuźni na gryfie, więc zanieś listę naszemu mistrzowi gryfów, Thorgrumowi Borrelsonowi, i pomów z nim o transporcie do Żelaznej Kuźni.', 'Zanieś listę Brocka Thorgrumowi Borrelsonowi w Thelsamarze.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(17, 'koKR', 'Dobra robota, $N, znów $gpokazałeś:pokazałaś;, ile jesteś $gwart:warta;! Te kapelusze będą ciekawym przedmiotem badań, ani chybi!$B$BA teraz, zgodnie z obietnicą, skosztuj jednego z mocniejszych przywracających wywarów z moich prywatnych zapasów...$B$BJeśli znasz się na alchemii, może zrobimy jeszcze jakiś interes. Tak czy owak, dziękuję ci za pomoc!', 0),
(161, 'koKR', 'Ach, no cóż, stary Hinderweir słusznie się martwi.', 0),
(199, 'koKR', 'To odkrycie jest, delikatnie mówiąc, niepokojące!', 0),
(217, 'koKR', 'Znakomicie, $N! $gTchnąłeś:Tchnęłaś; nadzieję w Loch Modan. Skoro Grawmug nie żyje, mamy większe szanse, by oczyścić te ziemie z troggów.', 0),
(224, 'koKR', 'Dobra robota, $N! $gWykazałeś:Wykazałaś; się na polu bitwy niezwykłą odwagą. Takim wysiłkiem wygramy wojnę z troggami. Dobrze $gsłużyłeś:służyłaś; królowi Magniemu.$b$bJeśli uważasz, że taka przygoda to coś dla ciebie, radzę ci pomówić z górskim strażnikiem Żwirogębym. Kapitan przydzielił go do ciężkiego patrolu i jestem pewien, że przyda mu się pomoc. Znajdziesz Żwirogębego zaraz w środku wieży.', 0),
(237, 'koKR', 'Dobrze $gwykonałeś:wykonałaś; zadanie. Sam król byłby dumny.$b$bObiecane posiłki jednak nie przybyły. Podobno front Przymierza to morze szkarłatu od krwi naszych poległych braci. Na wieść o takich stratach człowiekowi robi się gorzko w ustach. Ale nie możemy pozwolić, by ich śmierć poszła na marne. W tych ponurych czasach musimy się zjednoczyć i przywrócić Przymierzu chwałę.$b$bPomów z górskim strażnikiem Ścianotłukiem, dostaniesz nowy przydział. Teraz jesteś $gpotrzebny:potrzebna; bardziej niż kiedykolwiek.', 0),
(250, 'koKR', 'W podejrzanie wyglądającej beczce jest dziwnie pachnący proszek.', 0),
(255, 'koKR', 'Ach, to znakomite wieści! Ja i mieszkańcy Thelsamaru bardzo doceniamy twój trud. Co więcej, jeśli rozwiążemy problem z ograma, będziemy mogli zająć się tymi przeklętymi przez Światłość troggami.', 0),
(256, 'koKR', 'Fuj! Co to jest? I po co to przyni...$b$bA niech to...! Czy to...? Niech mnie Światłość spali, to głowa tego przeklętego ogra? No, to się nazywa zdobycz! Proszę, oto twoja nagroda i podziękowania ode mnie i mieszkańców Thelsamaru.', 0),
(257, 'koKR', 'Co? Udało się?$B$BPosłuchaj mojej rady, $Nuś, i nie daj, żeby ci to uderzyło do głowy. Przecież każdy golowąs z łukiem ustrzeliłby takie... małe okazy. I mam nadzieję, że zabijanie sępów nie sprawia ci aż takiej frajdy, co? Nie chcielibyśmy, żeby wyginęły.$B$BNo, eee... Niech nikt nie mówi, że Daryl Śmiały nie dotrzymuje słowa.', 0),
(258, 'koKR', 'Wyglądasz na trochę $gsponiewieranego:sponiewieraną;. Pewnie dziki dały ci się we znaki, hm? Nie martw się, nikomu nie powiem o twoich zmaganiach. Wyobrażam sobie, jak ci ciężko i bez gadania złych języków.$B$BOch! Udało ci się zabić te dziki? Ja... no, to znaczy... to znaczy, wcale mnie to nie dziwi! Każde dziecko by... zakład?$B$BJaki zakład?', 0),
(263, 'koKR', 'Gdy tylko cię ujrzałem, $N, wiedziałem, że przyniesiesz Żelaznej Kuźni chlubę. Dobrze $gsłużyłeś:służyłaś; królowi Magniemu. Skoro $gdowiodłeś:dowiodłaś;, że $gjesteś tak wiernym sprzymierzeńcem:jesteś tak wierną sprzymierzeńczynią; Królestwa, może pomów z kapitanem, czy nie powierzy ci ważniejszego zadania.$B$BSalutuję ci, $N.', 0),
(267, 'koKR', 'Jestem pod wrażeniem, $N. Broniąc naszych ziem, $gwyświadczyłeś:wyświadczyłaś; krasnoludzkiej rasie wielką przysługę. Sam król Magni Miedziobrody byłby dumny!', 0),
(271, 'koKR', 'Eee... co to? Wygląda na łeb niedźwiedzia.$B$B<Bezwiednie wodzi palcem po bliźnie.>$B$BNo, całkiem ciekawą zdobycz sobie $gupolowałeś:upolowałaś;. To nie może być ten niedźwiedź z tamtych czasów...$B$B<Milknie i zaczyna wyraźnie się trząść.>$B$BOch, zabierz to, zabierz! Wynoś stąd to paskudztwo!', 0),
(273, 'koKR', 'Hmpf, zasadzka Czarnorytych to za mało, żeby wstrzymać dostawy!$b$bAle Saean... Nigdy bym nie podejrzewał, że trzyma z nimi. Pracujemy z nim prawie od roku... może przegapiłem jakieś znaki.$b$bNo nic, zastanowię się nad tym później.', 0),
(274, 'koKR', 'Rozbrajający koloid? Na seaforium? O rety!', 0),
(278, 'koKR', 'W samą porę, $N!', 0),
(280, 'koKR', 'Beczułka lekko syczy, gdy rozbrajająca mieszanka osiada w środku.', 0),
(283, 'koKR', 'Stokrotne dzięki, $N!! $gUratowałeś:Uratowałaś; Kamienną Tamę! Bez twojej pomocy terroryści Czarnorytych z pewnością zniszczyliby tę potężną budowlę. Królestwo i Przymierze mogą być z ciebie dumne.$b$bTama znów jest bezpieczna. . . przynajmniej na razie. . . .', 0),
(297, 'koKR', 'Masz je! Dobra robota, $N!$B$BI nie wyglądasz na bardzo $gsponiewieranego:sponiewieraną;, choć wszędzie tam pełno rozszalałych troggów. Będę mieć cię na oku... dobrze się zapowiadasz.', 0),
(298, 'koKR', 'Ech! Ironband ma kłopoty z troggami. Ciekawe, czy ten proch strzelniczy potrzebny mu do kopania, czy do walki z tymi troggowymi bestiami...$b$bTak czy siak, dobrze wydany proch!$b$bAle dziwne jest to, że kilka tygodni temu wysłałem mu mnóstwo prochu. Ciekawe, gdzie się podział...', 0),
(307, 'koKR', '$gWidziałeś:Widziałaś; tam dużo koboldów? Nie mogę się doczekać rozkazu, żeby je wykurzyć z kopalni. Na samą myśl o tym, jak grzebią tymi brudnymi łapami w naszej kopalni, aż mi się w brzuchu przewraca!', 0),
(309, 'koKR', 'Och, dzięki Światłości, proch jest na miejscu. Ale przynosisz też niepokojące wieści. Pomyśleć, że Czarnoryci mają poplecznika, który potrafi zdobyć taki materiał na ich nikczemne plany.$b$bTo sprawa, którą ktoś inny zajmie się kiedy indziej. Ja muszę zrobić z tego prochu dobry użytek.', 0),
(385, 'koKR', 'No proszę, $gzebrałeś:zebrałaś; wyśmienite okazy, $N. Za materiał najwyższej jakości są dobre pieniądze, co do tego nie ma wątpliwości.', 0),
(416, 'koKR', 'Fuj! Kiedy prosiłem o te uszy, nie przyszło mi do głowy, że będą tak cuchnąć!$b$bOto twoja nagroda, $N. Dobra robota.', 0),
(418, 'koKR', 'Wierz mi, to się wydaje o wiele trudniejsze, niż wygląda, ale...$b$bOch, nigdy nie spotkałam nikogo, kogo by tak interesowało robienie kaszanki, ale na wszelki wypadek dam ci przepis. Proszę bardzo, tylko jedz ją świeżą!', 0),
(436, 'koKR', 'Jern chce wiedzieć, skąd opóźnienia, co?$b$bIronband szykuje najnowszy raport z postępów ze wszystkimi szczegółami, ale mogę ci powiedzieć jedno:$b$bTo przez troggi!!', 0),
(454, 'koKR', 'Witaj.$b$bTo ty masz mnie eskortować na wykopaliska? Dobrze to słyszeć... Po tym, co wyprawiali Saean i jego kumple, kto wie, co jeszcze Czarnoryci mają w zanadrzu?$b$bTak czy owak, pozwól, że zrobię ostatnie sprawdzenie. Porozmawiaj ze mną znowu, kiedy będziesz $ggotów:gotowa;.', 0),
(455, 'koKR', 'Twój raport jest pełen złych wieści!$b$bWidzę, że Smocze Paszcze mocno napierają na Algaz. Zwykle siedzą ukryte na wzgórzach. Co pchnęło je do Algaz, pozostaje tajemnicą...$b$bDziękuję, $N. Pewnie jeszcze będziemy potrzebować twojej pomocy z tymi orkami.', 0),
(468, 'koKR', 'Witaj! Przychodzisz w sprawie wyprawy zwiadowczej, tak? Bardzo dobrze!$b$bMam nadzieję, że twój ekwipunek jest w dobrym stanie, bo ta „zwiadowcza” wyprawa zmieniła się w coś bardziej krwawego...', 0),
(531, 'koKR', 'Dzięki, że $gpomogłeś:pomogłaś; mi z moim małym planem, $N. Od miesięcy aż mnie świerzbiło, żeby odegrać się na tym zadufanym, nadętym chłopaczku, i powiedziałabym, że poszło nam całkiem nieźle! Masz, weź to, $gzasłużyłeś:zasłużyłaś;.', 0),
(704, 'koKR', 'Dobra robota! Przy odrobinie szczęścia i pilności znajdziemy związek, jaki łączy troggi z tymi starożytnymi artefaktami.$B$B$gWyświadczyłeś:Wyświadczyłaś; poszukiwaczom wielką przysługę, $N. Twój trud nie zostanie zapomniany. Podobnie jak Agmond.', 0),
(721, 'koKR', 'Tak? Wybacz... <kaszel> Taki jestem słaby. Podejdziesz bliżej?$B$BRyedol cię przysłał? Chwała Muradinowi, ten chłopak nie jest taki tępy, jak kiedyś myślałem. <kaszel>', 0),
(722, 'koKR', 'Ha! <kaszel, kaszel>$B$BWiedziałem, że znajdziesz mój amulet, $N.$B$B<świszczy> Naprawdę dobra robota, $N. <kaszel>', 0),
(723, 'koKR', 'Amulet Młotopalcego? Chyba lżej mi było na duchu, kiedy tylko myślałem, że nie żyje. Pewność tylko pogłębia ból. Ten amulet to było dzieło jego życia. Nie mogę pozwolić, żeby jego śmierć poszła na marne.', 0),
(738, 'koKR', 'Ten szkielet to z pewnością nieszczęsne szczątki Agmonda. Ciało jest połamane i posiniaczone, a kości ogryzione do czysta.', 0),
(739, 'koKR', 'To otrzeźwiające wieści, $N. Ale Agmond miał silne ramię i potężny zamach młotem, a czaszkę twardą jak mało kto! Choć zabiły go te przeklęte troggi, jestem pewien, że wiele z nich zabrał ze sobą.', 0),
(1339, 'koKR', 'Zgadza się. Mam zadanie, którego nie mogę wykonać, bo stoję na warcie. Właściwie zaprowadzi cię daleko od Loch Modan.$B$BIdealna okazja do przygody!', 0),
(1655, 'koKR', 'Tak, tak, to ta. Ha! Gdybym wiedział, że naprawdę tam pójdziesz i będziesz się bić z tymi ogrami, dałbym ci całą listę rzeczy do przyniesienia, a nie tylko tę jedną. Ale ty tu nie robisz interesów dla mnie, co?$B$BUmowa to umowa; Jordan chciał dostawę mojego stopu, to ją dostanie.$B$BPozdrów go ode mnie i uważaj na siebie.', 0),
(2038, 'koKR', '$gWyświadczyłeś:Wyświadczyłaś; naszej sprawie wielką przysługę, $N. Troggi i trędowate gnomy, które opanowały Gnomoregan, wkrótce poczują pełną siłę gnomiego ataku z powietrza!', 0),
(2500, 'koKR', 'Ach, dobra robota, $N. To powinno mi wystarczyć przynajmniej na jakiś czas. Oto twoja zapłata, jak obiecałem.$B$BJeśli cię to interesuje, przydałoby mi się jeszcze trochę innych składników. Te jednak występują tylko w głębi wykopalisk w Uldamanie. Nie będzie łatwo je zdobyć, ale opłaci ci się, jeśli zechcesz znów mi pomóc.$B$BMoże coś więcej niż kilka błyszczących monet, co?', 0),
(2501, 'koKR', 'Od alchemika dla alchemika – chylę czoła. Masz, weź ten przepis i zapamiętaj go dobrze. Niech przyniesie ci tyle sukcesów i nagród, ile mnie przez te wszystkie lata!', 0),
(3181, 'koKR', 'Co tam masz? Podróbkę, to jasne!$B$BStałam oko w oko z Margol i wiem na pewno, że jej róg jest co najmniej osiem razy większy od tego, który trzymasz w rękach, $N. Pewnie $gzdjąłeś:zdjęłaś; go z jakiegoś burzoryja na Pustkowiach. O nie, $gmój drogi:moja droga;, Kamyczek nie da się nabrać!', 0),
(6387, 'koKR', 'Musisz to dostarczyć do Żelaznej Kuźni, co? Za niewielką opłatą mogę cię posadzić na grzbiecie jednego z moich gryfów, a ten cię tam zaniesie. Co ty na to?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(17, 'koKR', 'Masz już purpurowe kapelusze grzyba, których potrzebuję do moich alchemicznych prac? Nie ma kapeluszy – nie ma nagrody!', 0),
(161, 'koKR', 'Co mówisz, $gsynku:córciu;? Nic nie słyszę, tylko mi w uszach dzwoni. Ej, a co ty tam masz?', 0),
(199, 'koKR', 'Udało ci się znaleźć jakieś tropy, $N?', 0),
(217, 'koKR', 'Grawmug i jego dwaj strażnicy, Zgrzytacz i Zabijaka, wciąż żyją. Twoje zadanie nie jest skończone, dopóki cała trójka nie zginie. Krasnoludzkie imperium na ciebie liczy, $N.', 0),
(224, 'koKR', 'Loch Modan jest w oblężeniu, $N! Potrzebujemy każdego członka Przymierza, który zdolny jest do walki. $gZabiłeś:Zabiłaś; już 10 troggów z Kamiennych Drzazg i 10 zwiadowców z Kamiennych Drzazg?', 0),
(237, 'koKR', 'Potrzebujemy więcej czasu. Masz rozkaz zabić 10 czaszkotłuków z Kamiennych Drzazg i 10 jasnowidzów z Kamiennych Drzazg. Nie dawaj wrogowi wytchnąć, dopóki nie dostaniemy posiłków. To nie czas na próżnowanie.', 0),
(255, 'koKR', 'Udało się coś zdziałać?', 0),
(256, 'koKR', 'Tak? Mogę coś dla ciebie zrobić?', 0),
(257, 'koKR', 'Nie wyszło? Nie przejmuj się, $Nek...$B$BNie każdy może być mną.', 0),
(258, 'koKR', 'To zupełnie naturalne, że się nad sobą użalasz, kiedy przyćmił cię ktoś tak nowy na tym świecie. Nie przejmuj się, $Nowicz.$B$BHm? Przekręciłem twoje imię?', 0),
(263, 'koKR', 'Już z powrotem? Gdybym nie wyraził się jasno: masz zabić 10 szamanów z Kamiennych Drzazg i 10 kościołamów z Kamiennych Drzazg, $N. A teraz dalej, bierz ich, $gPogromco:Pogromczyni; Troggów!', 0),
(267, 'koKR', 'Masz 8 kamiennych zębów trogga? Jeśli nie, zostało jeszcze sporo do zrobienia, $N.', 0),
(271, 'koKR', 'Ach, $N! Już z powrotem? Pewnie znów $gbyłeś:byłaś; na łowach? Nie martw się, jeśli ci nie poszło, na dłuższą metę wyjdzie ci to na dobre!$B$B... I tak gorzej już być nie może...', 0),
(274, 'koKR', 'Co przynosisz od Ashlana?', 0),
(278, 'koKR', 'Masz, co trzeba? Czas nagli!!', 0),
(280, 'koKR', 'Wieko beczułki powoli się odkręca.', 0),
(297, 'koKR', 'Masz te bożki? Musimy je zbadać i przekazać nasze odkrycia do Żelaznej Kuźni!', 0),
(298, 'koKR', 'O, raport z postępów prac na wykopaliskach? Bardzo dobrze!', 0),
(307, 'koKR', 'Masz ten sprzęt górników, $N?', 0),
(385, 'koKR', 'Opowiadałem ci, jak o mało nie straciłem ręki przez jednego z tych krokodyli? Paskudne bydlę, zęby jak noże. Ale miałem szczęście... Zablokowałem mu szczęki nożem. Ten nóż wciąż mam gdzieś tutaj...', 0),
(416, 'koKR', 'Witaj, $N. Jak idzie łapanie szczurów?', 0),
(418, 'koKR', 'Jestem gotowa, żeby zacząć gotować. Masz dla mnie składniki?', 0),
(455, 'koKR', 'Idziesz z Loch Modan? Jak wygląda sytuacja z orkami przy Bramie Algaz?', 0),
(531, 'koKR', 'Świetna robota, $N! Ale mu pokazaliśmy! Daj mi tę głowę, ja się nią zajmę.', 0),
(704, 'koKR', '$gZnalazłeś:Znalazłaś; te urny, $N? Musimy odkryć, co je łączy z troggami!', 0),
(722, 'koKR', 'Klan Cienistej Kuźni... <kaszel> jest groźny. Uważaj na siebie. <kaszel> Musisz znaleźć ten amulet.', 0),
(723, 'koKR', 'Powiedziałbym, że to był zły dzień, ale to Bezludzie: tu każdy dzień jest zły.', 0),
(739, 'koKR', 'Masz wieści o losie Agmonda? $gOdnalazłeś:Odnalazłaś; go?', 0),
(1655, 'koKR', 'I jak, udało się? Haha, te ogry jeszcze cię nie pokonały, co?', 0),
(2038, 'koKR', '$N! Gdzie są moje rzeczy?!', 0),
(2500, 'koKR', 'Masz już to, czego potrzebuję? Nie dostaniesz zapłaty, dopóki nie przyniesiesz mi tych składników.', 0),
(2501, 'koKR', '$gUżyłeś:Użyłaś; już naczyń, żeby zdobyć dla mnie krew osmalonych strażników? Tak, wiem, to niebezpieczne zadanie... ale przepis na mój przywracający wywar czeka na twój sukces. Ryzyko i nagroda, przyjacielu... ryzyko i nagroda...', 0),
(3181, 'koKR', 'Nie, nie otworzę bramy.', 0),
(6387, 'koKR', 'Już masz dość Thelsamaru? $gGotowy:Gotowa; ruszać do innego miasta?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(1139, 0, 'koKR', 'No witaj, $gobywatelu:obywatelko;. Nazywam się Tęponosy, sędzia Tęponosy, jeśli chodzi o ścisłość. Mam pieczę nad pomyślnością Thelsamaru i wierz mi, zawsze przyda się nam tu kolejna para silnych rąk!', 0);
