INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(434, 'koKR', 'Giń w imię Ragnarosa!', '', 0),
(435, 'koKR', 'Most Thandol padł w imię Ragnarosa. Tak samo padnie Kamienna Tama!', '', 0),
(436, 'koKR', 'Król Magni Miedziobrody to głupiec i szarlatan!', '', 0),
(443, 'koKR', 'Słabeusz! Nie masz szans z plemieniem Kamiennych Drzazg!', '', 0),
(444, 'koKR', 'Jakiś $C imieniem $n? Będzie z ciebie niezłe śniadanie!', '', 0),
(445, 'koKR', 'Plemię Kamiennych Drzazg zgotuje ci zgubę!', '', 0),
(446, 'koKR', 'Giń! Te ziemie należą do plemienia Kamiennych Drzazg!', '', 0),
(447, 'koKR', 'Dobry $R to martwy $R!', '', 0),
(448, 'koKR', 'Loch należy teraz do plemienia Kamiennych Drzazg, $n! A teraz giń!', '', 0),
(498, 'koKR', 'Ach, nareszcie na miejscu! Ale będzie ulga pozbyć się tych beczek.', '', 0),
(510, 'koKR', 'Pomocy! Mam tylko jedną rękę do obrony!', '', 0),
(511, 'koKR', 'Niech idą! Nie boję się jakichś chuderlawych bestii!', '', 0),
(540, 'koKR', 'Żaden nędzny zdrajca nie przeszkodzi, żeby proch dotarł do Ironbanda!', '', 0),
(546, 'koKR', 'Kamienna Tama ocalona! Trzykrotne hura na cześć $n!', '', 0),
(637, 'koKR', '%s zapala dynamit, a jego oczy rozbłyskują czerwienią. Zaczyna szaleńczo rechotać!', '', 0),
(638, 'koKR', 'Łehehe! Zabiorę cię ze sobą!', '', 0),
(957, 'koKR', 'Spiesz się... <kaszel, kaszel> Znajdź... <kaszel> Ryedola...', '', 0),
(979, 'koKR', '%s osuwa się na ziemię. Z ostatnim tchnieniem jego duch odchodzi.', '', 0),
(995, 'koKR', 'Świeży chleb! Chleb prosto z pieca!', '', 0),
(996, 'koKR', 'Kupujcie, póki świeże i pachnące! Bochenki chleba!', '', 0),
(997, 'koKR', 'Wszelkie rodzaje chleba! Pieczone dzisiaj. Kupujcie, póki są!', '', 0),
(998, 'koKR', 'Chleb! Bochenki waszych ulubionych! Świeżutkie!', '', 0),
(1920, 'koKR', 'Hau! Moja zabić!', 'Hau! Moja zabić!', 0),
(1921, 'koKR', 'Moja nie uciekać przed taki $C jak ty!', 'Moja nie uciekać przed taki $C jak ty!', 0),
(1928, 'koKR', 'Ten $R wyglądać smaczny!', '', 0),
(1929, 'koKR', 'Walić to!', '', 0),
(1930, 'koKR', 'Moja cię miażdżyć!', '', 0),
(1931, 'koKR', 'Hę? Co to?', '', 0),
(1937, 'koKR', 'Za Smocze Paszcze!', 'Za Smocze Paszcze!', 0),
(1938, 'koKR', 'Twoje kości pękną pod moim butem!', 'Twoje kości pękną pod moim butem!', 0),
(1939, 'koKR', 'Niech żyją Smocze Paszcze! Giń, nędzny robaku!', 'Niech żyją Smocze Paszcze! Giń, nędzny robaku!', 0),
(5830, 'koKR', 'Tu, w Stróżówce Obieżyświatów, ponad wszystko cenimy umiejętności łowieckie. Chcesz zyskać moje uznanie? Musisz na nie zapracować.$B$BWyglądasz na $ggotowego:gotową; na takie wyzwanie, $gchłopcze:dziewczyno;!', '', 0),
(5831, 'koKR', '$gWyrosłeś:Wyrosłaś; na $gniezłego łowcę:niezłą łowczynię;, $n! Nie tylko $gdowiodłeś:dowiodłaś; swoich umiejętności, ale też $gutarłeś:utarłaś; nosa Darylowi, a to u mnie liczy się podwójnie!$B$BZawsze jesteś tu mile $gwidziany:widziana;.', '', 0),
(5854, 'koKR', '', 'Zdobądź ten łeb, a Daryl na pewno się przestraszy. Nie żeby na to nie zasłużył, ten przeklęty zarozumiały głupek. Ale ha! Nie mogę się doczekać, żeby zobaczyć jego minę, kiedy mu go pokażesz.', 0),
(5855, 'koKR', '', 'Witaj w Stróżówce Obieżyświatów, $n!', 0),
(5858, 'koKR', '', 'Zawsze jesteś tu mile $gwidziany:widziana;, $n. Dzięki za tę uciechę – i nie przejmuj się Darylem, należało mu się!', 0),
(7692, 'koKR', 'Czy to moja słodka Kali przysłała cię do mnie? To moje oczko w głowie.', '', 0),
(7799, 'koKR', 'Gdzie mój kręciołek? Przed chwilą gdzieś tu był...', '', 0),
(8113, 'koKR', 'Dowożenie tych beczek na wykopaliska to ciężka praca, ale tylu liczy na to, że dostarczymy tam proch strzelniczy.$B$BMusimy robić, co w naszej mocy, przeciw Czarnorytym!', '', 0);
